    ("q-ai-nn-001", "c-ai-nn-001", "Repeat", "Which of the following are true about the perceptron model?", ["It can learn non-linear decision boundaries without hidden layers.", "It updates weights based on the error of its prediction.", "It uses a step function as its activation.", "It was originally designed as a hardware implementation.", "It uses backpropagation to update its weights."], [1, 2, 3], "A standard perceptron updates weights based on errors, uses a step function, and was originally designed as hardware (Mark I Perceptron). It cannot learn non-linear boundaries on its own and uses the perceptron learning rule.", -1.2, 1.0),
    ("q-ai-nn-002", "c-ai-nn-001", "Repeat", "Which of these are characteristics of the Sigmoid activation function?", ["It outputs values strictly between -1 and 1.", "It outputs values strictly between 0 and 1.", "It suffers from the vanishing gradient problem for large input magnitudes.", "It is a linear function.", "Its derivative can be expressed in terms of the function itself."], [1, 2, 4], "Sigmoid outputs (0, 1), suffers from vanishing gradients when inputs are large, and its derivative is f(x)(1-f(x)). It is non-linear and not (-1, 1).", -1.0, 1.2),
    ("q-ai-nn-003", "c-ai-nn-001", "Repeat", "What are the primary advantages of the ReLU (Rectified Linear Unit) activation function?", ["It completely eliminates the vanishing gradient problem for all inputs.", "It is computationally efficient compared to Sigmoid or Tanh.", "It induces sparsity in the hidden units.", "It is bounded between -1 and 1.", "It does not suffer from vanishing gradients for positive inputs."], [1, 2, 4], "ReLU is fast to compute, creates sparse representations by outputting 0 for negative inputs, and does not saturate for positive inputs. It can suffer from the 'dying ReLU' problem for negative inputs.", -0.8, 1.1),
    ("q-ai-nn-004", "c-ai-nn-001", "Summary", "How does the choice of activation function impact the training of deep neural networks?", ["Non-linear activations allow the network to learn complex, non-linear mappings.", "Using linear activations in all layers makes the network equivalent to a single-layer linear regression model.", "The choice of activation function dictates the number of layers required.", "Activation functions determine the learning rate of the optimizer.", "Certain activation functions can cause gradients to vanish, severely impeding training in deep networks."], [0, 1, 4], "Non-linear functions allow learning of non-linear mappings. Deep linear networks collapse to single linear layers. Activation functions like Sigmoid can cause vanishing gradients in deep networks.", 0.2, 1.3),
