with open('/Users/dantepilla/Documents/Antigravity/IKAS/knowledge-graph/schema/seed_neural_networks.cypher', 'w') as f:
    # 1. Topic
    f.write("// 1. Topic\n")
    f.write("MATCH (s:Subject {id: \"s-ai\"});\n")
    f.write("CREATE (t:Topic {id: \"t-ai-neural-networks\", name: \"Neural Networks & Deep Learning\"});\n")
    f.write("CREATE (s)-[:CONTAINS]->(t);\n\n")

    # 2. Concepts
    f.write("// 2. Concepts\n")
    for c in concepts:
        f.write(f"CREATE (c:Concept {{id: \"{c['id']}\", name: \"{c['name']}\", description: \"{c['desc']}\"}});\n")
    f.write("\n")
    f.write("MATCH (t:Topic {id: \"t-ai-neural-networks\"}), (c:Concept) WHERE c.id STARTS WITH 'c-ai-nn-' CREATE (t)-[:CONTAINS]->(c);\n\n")
    
    for c in concepts:
        f.write(f"MATCH (c:Concept {{id: \"{c['id']}\"}}), (cc:ConceptClass {{id: \"{c['class']}\"}}) CREATE (c)-[:INSTANCE_OF]->(cc);\n")
    f.write("\n")

    # Prereqs
    f.write("// Prerequisite relationships between concepts\n")
    f.write("MATCH (c1:Concept {id: \"c-ai-nn-001\"}), (c2:Concept {id: \"c-ai-nn-002\"}) CREATE (c1)-[:PREREQUISITE_FOR]->(c2);\n")
    f.write("MATCH (c2:Concept {id: \"c-ai-nn-002\"}), (c3:Concept {id: \"c-ai-nn-003\"}) CREATE (c2)-[:PREREQUISITE_FOR]->(c3);\n")
    f.write("MATCH (c2:Concept {id: \"c-ai-nn-002\"}), (c4:Concept {id: \"c-ai-nn-004\"}) CREATE (c2)-[:PREREQUISITE_FOR]->(c4);\n")
    f.write("MATCH (c4:Concept {id: \"c-ai-nn-004\"}), (c5:Concept {id: \"c-ai-nn-005\"}) CREATE (c4)-[:PREREQUISITE_FOR]->(c5);\n")
    f.write("MATCH (c3:Concept {id: \"c-ai-nn-003\"}), (c6:Concept {id: \"c-ai-nn-006\"}) CREATE (c3)-[:PREREQUISITE_FOR]->(c6);\n")
    f.write("MATCH (c5:Concept {id: \"c-ai-nn-005\"}), (c6:Concept {id: \"c-ai-nn-006\"}) CREATE (c5)-[:PREREQUISITE_FOR]->(c6);\n\n")

    # 3. Resources
    f.write("// 3. Resources\n")
    for i, c in enumerate(concepts, 1):
        rid = f"r-c-ai-nn-00{i}"
        f.write(f"CREATE (r:Resource {{id: \"{rid}\", url: \"https://example.com/{rid}\", type: \"video\", title: \"Introduction to {c['name']}\"}});\n")
        f.write(f"MATCH (c:Concept {{id: \"{c['id']}\"}}), (r:Resource {{id: \"{rid}\"}}) CREATE (c)-[:LINKED_RESOURCE]->(r);\n")
    f.write("\n")

    # 4. Questions
    f.write("// 4. Generate 50 questions\n\n")
    
    current_concept = ""
    for q in questions:
        qid, cid, level, stem, options, corr_indices, expl, diff, disc = q
        if cid != current_concept:
            f.write(f"\n// --- {cid} ---\n")
            current_concept = cid
        
        corr_answers = [options[i] for i in corr_indices]
        
        opt_json = json.dumps(options).replace("'", "\\'")
        corr_json = json.dumps(corr_answers).replace("'", "\\'")
        expl_escaped = expl.replace('"', '\\"').replace("'", "\\'")
        stem_escaped = stem.replace('"', '\\"').replace("'", "\\'")

        # Cypher CREATE statement
        f.write(f"CREATE (q:Question {{id: \"{qid}\", stem: \"{stem_escaped}\", level: \"{level}\", question_type: \"mcq_multi\", options: '{opt_json}', correct_answers: '{corr_json}', explanation: \"{expl_escaped}\", difficulty: {diff}, discrimination: {disc}, guessing: 0.25, time_estimate_seconds: 60}});\n")
        f.write(f"MATCH (c:Concept {{id: \"{cid}\"}}), (q:Question {{id: \"{qid}\"}}) CREATE (c)-[:HAS_QUESTION]->(q);\n")
    f.write("\n")

    # 5. Question Prerequisites (chaining them within concepts as instructed: 001 -> 002 -> 004 -> 006)
    f.write("// 5. Prerequisite relationships between questions within concepts\n")
    
    for cid in set([q[1] for q in questions]):
        cq = [q for q in questions if q[1] == cid]
        cq = sorted(cq, key=lambda x: x[0])
        
        repeat_q = [q for q in cq if q[2] == "Repeat"]
        summary_q = [q for q in cq if q[2] == "Summary"]
        int_q = [q for q in cq if q[2] == "Intuitive"]
        apply_q = [q for q in cq if q[2] == "Apply"]
        
        # Example chaining: repeat1 -> repeat2 -> summary1 -> intuitive1 -> apply1
        chain = []
        if len(repeat_q) >= 2:
            chain.extend([repeat_q[0], repeat_q[1]])
        if summary_q:
            chain.append(summary_q[0])
        if int_q:
            chain.append(int_q[0])
        if apply_q:
            chain.append(apply_q[0])
            
        for i in range(len(chain)-1):
            q1, q2 = chain[i][0], chain[i+1][0]
            f.write(f"MATCH (q1:Question {{id: \"{q1}\"}}), (q2:Question {{id: \"{q2}\"}}) CREATE (q1)-[:PREREQUISITE_FOR]->(q2);\n")

